/**
 * Glyph metrics for the SDF font atlas (generated by tools/generate_font.py).
 */

export class Font {
  constructor(meta) {
    this.meta = meta;
    this.glyphs = meta.glyphs;
    this.size = meta.size;
    this.ascent = meta.ascent;
    this.descent = meta.descent;
    this.fallback = this.glyphs['?'];
  }

  glyph(ch) {
    return this.glyphs[ch] || this.fallback;
  }

  measure(text, size) {
    const k = size / this.size;
    let w = 0;
    for (const ch of text) w += this.glyph(ch).advance;
    return w * k;
  }

  /** Splits text into lines no wider than maxWidth. */
  wrap(text, size, maxWidth) {
    const lines = [];
    for (const paragraph of String(text).split('\n')) {
      let line = '';
      for (const word of paragraph.split(' ')) {
        const candidate = line ? `${line} ${word}` : word;
        if (line && this.measure(candidate, size) > maxWidth) {
          lines.push(line);
          line = word;
        } else {
          line = candidate;
        }
      }
      lines.push(line);
    }
    return lines;
  }
}
